import itertools

def solve_for_k(n_A, n_C, k):
    configs = list(itertools.combinations(range(n_A + n_C), n_A))
    # A configuration is a tuple of 0s and 1s, where 1 is A and 0 is C.
    # However, it's better to use a list of 'A' and 'C'.
    all_configs = []
    for combo in configs:
        config = []
        for i in range(n_A + n_C):
            if i in combo:
                config.append('A')
            else:
                config.append('C')
        all_configs.append(tuple(config))

    for config in all_configs:
        current = list(config)
        visited = set()
        path = []
        while True:
            path.append(tuple(current))
            if tuple(current) in visited:
                break
            visited.add(tuple(current))

            # Count boundaries
            boundaries = 0
            for i in range(len(current) - 1):
                if current[i] != current[i+1]:
                    boundaries += 1

            if boundaries <= 1:
                break

            # Find k-th coin
            idx = k - 1
            coin = current[idx]

            # Find run
            start = idx
            while start > 0 and current[start-1] == coin:
                start -= 1
            end = idx
            while end < len(current) - 1 and current[end+1] == coin:
                end += 1

            # Run is current[start:end+1]
            run = current[start:end+1]
            new_config = run + current[:start] + current[end+1:]
            current = new_config

    return True

def check_k(n_A, n_C, k):
    # Instead of checking all, let's check some.
    # But for small n_A, n_C, we can check all.
    return solve_for_k(n_A, n_C, k)

