def get_boundaries(config):
    count = 0
    for i in range(len(config) - 1):
        if config[i] != config[i+1]:
            count += 1
    return count

def perform_op(config, k):
    k_idx = k - 1
    coin = config[k_idx]
    start = k_idx
    while start > 0 and config[start-1] == coin:
        start -= 1
    end = k_idx
    while end < len(config) - 1 and config[end+1] == coin:
        end += 1
    block = config[start:end+1]
    remaining = config[:start] + config[end+1:]
    return block + remaining

def solve(n_a, n_c):
    n = n_a + n_c
    configs = list(set(itertools.permutations([ 'A' ] * n_a + [ 'C' ] * n_c)))
    for k in range(1, n + 1):
        all_reach_condition = True
        for config in configs:
            current = config
            visited = set()
            while get_boundaries(current) > 1:
                if current in visited:
                    all_reach_condition = False
                    break
                visited.add(current)
                current = perform_op(current, k)
            if not all_reach_condition:
                break
        if all_reach_condition:
            print(f"k={k} is a solution")
        else:
            print(f"k={k} is NOT a solution")

